/* Generated by tools/build.js from data/isc2-cc.js. Edit that file, not this one. */
CertHub.addQuestions("isc2-cc", [["ic1",0,1,"A hospital must ensure patient records are not changed without authorization. Which security principle is the main concern?",["Confidentiality","Availability","Integrity","Non-repudiation"],2,"Integrity protects data from unauthorized or accidental modification.","Outline Domain 1",["Confidentiality is about keeping records from being seen by unauthorized people, not about preventing changes to them.","Availability ensures records can be reached when needed; it does not stop unauthorized modification.",null,"Non-repudiation proves who performed an action so they cannot deny it; it does not by itself prevent records from being altered."],2],["ic2",0,1,"In AAA, what does accounting provide?",["A record of what a user did so actions can be traced","Proof of who the user is","A decision about what the user may access","Encryption of the user's session"],0,"Accounting logs user activity for auditing and tracing; authentication proves identity and authorization grants access.","Outline Domain 1",[null,"Proving who the user is describes authentication, the step before any activity is recorded.","Deciding what a user may access is authorization, not the logging of what they actually did.","Encrypting the session protects confidentiality in transit and is not one of the AAA functions."],1],["ic3",0,1,"A company buys cyber insurance to cover losses from a data breach. Which risk treatment is this?",["Avoidance","Mitigation","Acceptance","Transference"],3,"Insurance shifts the financial impact of the risk to another party, which is transference.","Outline Domain 1",["Avoidance means stopping the risky activity altogether; buying insurance keeps the activity and only shifts the financial loss.","Mitigation applies controls to reduce likelihood or impact; insurance does not make a breach less likely or less damaging, it just pays for it.","Acceptance means knowingly bearing the risk yourself, whereas insurance passes the cost to the insurer.",null],2],["ic4",0,1,"Which of the following is an administrative (managerial) control?",["Firewall","Acceptable use policy","Door lock","Disk encryption"],1,"Policies are administrative controls; firewalls and encryption are technical, and locks are physical.","Outline Domain 1",["A firewall is a technical (logical) control that filters traffic, not a management-level rule or process.",null,"A door lock is a physical control that restricts access to a space.","Disk encryption is a technical control implemented in software or hardware, not an administrative policy."],1],["ic5",0,1,"An ISC2 member learns that a colleague is falsely claiming to hold the CC certification. What is the best action?",["Ignore it because it is not their business","Report it through ISC2's ethics complaint process","Post the colleague's name on social media","Ask the colleague to share their exam questions"],1,"The Code of Ethics calls for acting honorably and advancing the profession, which includes reporting misrepresentation through proper channels.","Outline Domain 1",["The ISC2 Code of Ethics expects members to protect the profession, so ignoring known misrepresentation of a credential is not acceptable.",null,"Publicly shaming someone online is not a proper channel and could itself be unprofessional or defamatory.","Asking for exam questions would violate the exam's confidentiality agreement and does nothing about the false claim."],3],["ic6",0,1,"Which term describes the combination of the likelihood of a threat exploiting a weakness and the impact if it does?",["Vulnerability","Threat","Asset","Risk"],3,"Risk is measured by likelihood and impact.","Outline Domain 1",["A vulnerability is only the weakness itself; it does not combine likelihood and impact.","A threat is the potential cause of harm (such as an attacker); it is one input to risk, not the combination described.","An asset is the thing of value being protected, not a measure of likelihood and impact.",null],1],["ic7",0,1,"A user logs in with a password and a fingerprint scan. Which factor types are used?",["Something you know and something you are","Something you have and something you are","Two knowledge factors","Something you know and somewhere you are"],0,"A password is knowledge and a fingerprint is a biometric (inherence) factor.","Outline Domain 1",[null,"A password is not something you have; possession factors are items like a smart card, token or phone.","A fingerprint is a biometric (inherence) factor, so only one of the two is a knowledge factor.","A fingerprint is not a location factor; somewhere you are would be something like GPS or IP-based location."],2],["ic8",0,1,"An unpatched web server that an attacker could exploit is an example of a:",["Threat","Risk","Vulnerability","Control"],2,"A vulnerability is a weakness that a threat could exploit.","Outline Domain 1",["The threat would be the attacker or event that might exploit the server; the unpatched server itself is the weakness.","Risk is the likelihood and impact of the weakness being exploited, not the weakness itself.",null,"A control is a safeguard that reduces risk, such as applying the patch; an unpatched server is the opposite."],1],["ic9",0,1,"Security staff review camera footage to find out who entered a server room after hours. What type of control is the camera acting as?",["Preventive","Deterrent","Detective","Corrective"],2,"Reviewing footage to identify what happened is a detective function.","Outline Domain 1",["A preventive control stops an event before it happens; reviewing footage after the fact does not block anyone from entering.","Visible cameras can deter, but in this scenario the footage is being reviewed to identify who entered, which is detection.",null,"A corrective control fixes or restores something after an incident; identifying the person does not correct anything."],2],["ic10",0,1,"Which technology best provides non-repudiation for an email?",["Digital signature","Symmetric encryption","Unkeyed hashing","Load balancing"],0,"A digital signature made with the sender's private key proves who sent the message, so the sender cannot credibly deny it.","Outline Domain 1",[null,"Symmetric encryption uses a shared key, so either party could have produced the message and neither can prove who sent it.","An unkeyed hash shows whether data changed, but anyone can compute it, so it does not tie the message to a sender.","Load balancing distributes traffic for availability and has nothing to do with proving who sent an email."],2],["ic11",0,1,"Which document states management's high-level security intent and is mandatory?",["Guideline","Procedure","Baseline","Policy"],3,"A policy is the high-level mandatory statement of intent; the other documents support it.","Outline Domain 1",["Guidelines are recommended, optional advice, not mandatory statements of management intent.","Procedures are detailed step-by-step instructions that carry out a policy, not the high-level statement itself.","A baseline defines a minimum security configuration; it is a supporting, technical-level document rather than management's overall intent.",null],1],["ic12",0,1,"A company must protect personal data because the government requires it by law. What is the source of this requirement?",["An internal guideline","Legislation or regulation","An industry best practice","A vendor recommendation"],1,"Requirements imposed by government, such as GDPR, come from laws and regulations and are not optional.","Outline Domain 1",["An internal guideline is written by the company itself and is usually optional, not imposed by government.",null,"Industry best practices are voluntary recommendations, not legal requirements from the government.","A vendor recommendation is advice from a supplier and carries no legal force."],2],["ic13",0,1,"An attacker slips manipulated records into the data used to train a company's AI model. Which principle is mainly threatened?",["Availability","Integrity","Accounting","Non-repudiation"],1,"Data poisoning corrupts the training data, which attacks its integrity and the trustworthiness of the model's output.","Outline Domain 1",["Poisoned training data does not normally make the model unreachable; the problem is that its outputs become untrustworthy.",null,"Accounting is the logging of user actions in AAA, not a property of the training data that poisoning corrupts.","Non-repudiation is about proving who performed an action; slipping in bad records attacks the correctness of the data instead."],2],["ic14",0,1,"Which approach does a qualitative risk assessment use?",["Exact dollar values such as annualized loss expectancy","Only historical breach costs","Hash values of critical files","Ratings such as high, medium and low"],3,"Qualitative assessment ranks risks with descriptive ratings; quantitative assessment uses monetary values.","Outline Domain 1",["Exact dollar values such as ALE are used in quantitative risk assessment, not qualitative.","Relying only on historical breach costs is still a monetary, data-driven approach and is not how qualitative assessment rates risk.","File hashes are integrity checks, not a way of rating risk likelihood or impact.",null],1],["ic15",0,2,"Which measure is designed to warn leadership early that risk exposure is increasing?",["Key risk indicator (KRI)","Recovery point objective","Service level agreement","Mean time to repair"],0,"KRIs are metrics chosen specifically to signal rising risk before it becomes an incident.","Outline Domain 2",[null,"A recovery point objective defines acceptable data loss for recovery planning; it is not an early-warning metric for rising risk.","A service level agreement sets agreed service targets with a provider; it does not signal growing risk exposure.","Mean time to repair measures how quickly failures are fixed after they occur, not whether risk is trending upward."],2],["ic16",0,2,"What is the main purpose of security governance?",["Tuning firewall rules daily","Making users choose strong passwords","Ensuring security activities align with business objectives under leadership oversight","Running nightly backups"],2,"Governance sets direction, accountability and oversight so security supports business goals.","Outline Domain 2",["Daily firewall tuning is an operational task, not the leadership oversight and direction that governance provides.","Enforcing strong passwords is a specific technical or administrative control, not the purpose of governance as a whole.",null,"Running nightly backups is an operational activity that governance may require, but it is not governance itself."],2],["ic17",0,2,"What does an organization's risk appetite describe?",["The number of vulnerabilities found in scans","The cost of a security control","The amount of risk it is willing to accept to pursue its goals","The total value of its assets"],2,"Risk appetite is the level of risk leadership is willing to accept.","Outline Domain 2",["The number of scan findings measures vulnerabilities present, not how much risk leadership is willing to accept.","Control cost is an input to risk treatment decisions, not a statement of risk appetite.",null,"Total asset value helps size potential impact but does not express the organization's willingness to take risk."],1],["ic18",0,2,"Which approach is most effective for building a strong security culture?",["Ongoing awareness training backed by visible leadership support","A one-time onboarding slide deck","Publicly shaming employees who click phishing links","Emailing the policy once a year"],0,"Culture grows from continuous, relevant training and leaders who model the behavior; shaming discourages reporting.","Outline Domain 2",[null,"A one-time onboarding deck is quickly forgotten and does not sustain the behaviors that make up a security culture.","Public shaming discourages employees from reporting mistakes, which undermines the culture instead of strengthening it.","Emailing the policy once a year is passive and infrequent, so it rarely changes day-to-day behavior."],2],["ic19",0,2,"In GRC, what does compliance mean?",["Buying the newest security tools","Never having an incident","Hiring a chief information security officer","Meeting the requirements of applicable laws, regulations, standards and contracts"],3,"Compliance is conformance with external and internal requirements, such as PCI DSS or HIPAA.","Outline Domain 2",["Buying new tools does not by itself show conformance with any law, standard or contract.","Compliance does not guarantee zero incidents; a fully compliant organization can still be breached.","Hiring a CISO may support a security program, but compliance is about meeting requirements, not staffing a role.",null],1],["ic20",0,2,"The click rate on simulated phishing emails falls from 20% to 5% over a year. What does this metric mainly show?",["Email server availability","Effectiveness of the security awareness program","Encryption strength","Patch compliance"],1,"Phishing simulation results are a common measure of how well awareness training is changing behavior.","Outline Domain 2",["Email server availability would be measured by uptime, not by how many users click simulated phishing links.",null,"Phishing click rates reflect user behavior and say nothing about the strength of encryption algorithms.","Patch compliance tracks how many systems have current updates, which is unrelated to users clicking phishing emails."],2],["ic21",0,2,"Who is ultimately accountable for accepting risk in an organization?",["The help desk","Senior management and the board","Individual end users","The external auditor"],1,"Senior leadership owns risk decisions; security teams advise and auditors assess.","Outline Domain 2",["The help desk supports users and follows policy; it has no authority to accept organizational risk.",null,"End users must follow policy but are not accountable for organization-wide risk decisions.","External auditors independently assess controls and must stay independent, so they do not accept risk on the organization's behalf."],2],["ic22",0,2,"Which governance document gives step-by-step instructions for completing a task?",["Policy","Guideline","Baseline","Procedure"],3,"Procedures are detailed, step-by-step instructions that implement policies and standards.","Outline Domain 2",["A policy is a high-level statement of intent and does not give step-by-step instructions.","A guideline offers optional recommendations rather than detailed, required steps.","A baseline specifies a minimum configuration standard, not the sequence of steps to complete a task.",null],1],["ic23",0,2,"A security manager is preparing a report for executives. What should it focus on?",["Risk and program metrics summarized in business terms","Every raw log entry from the SIEM","The full list of firewall rules","Application source code"],0,"Executive reporting should translate security status into business risk so leaders can decide.","Outline Domain 2",[null,"Raw SIEM log entries are far too detailed for executives and do not translate into business risk they can act on.","A full firewall rule list is technical detail for engineers, not a summary executives can use to make decisions.","Application source code is irrelevant to an executive audience and says nothing about overall risk posture."],2],["ic24",0,2,"A new vendor will process the company's customer data. What should happen before the contract is signed?",["Give the vendor full administrator access","Skip review because the vendor is inexpensive","Assess the vendor's security and include security requirements in the contract","Wait until an incident occurs to review the vendor"],2,"Third-party risk management assesses vendors up front and writes security and notification terms into the contract.","Outline Domain 2",["Granting full admin access before any assessment violates least privilege and exposes the company to unvetted risk.","Low cost does not reduce the risk of handling customer data; the vendor still needs a security review.",null,"Waiting for an incident is reactive; by then contract terms and security requirements can no longer be negotiated up front."],2],["ic25",0,3,"Which statement best describes least privilege?",["All IT staff get administrator rights","Everyone gets the same access for simplicity","Users get only the access they need to do their job","Access is granted based on seniority"],2,"Least privilege limits each user to the minimum access their job requires.","Outline Domain 3",["Giving every IT staff member admin rights grants far more access than most roles need, the opposite of least privilege.","Giving everyone identical access ignores job needs and overprivileges most users.",null,"Seniority does not determine need; senior staff often require less system access than specialists."],1],["ic26",0,3,"Which is an example of separation of duties?",["One employee creates vendor payments and a different employee approves them","One administrator holds every password","Team members share one login","A manager approves their own expense report"],0,"Splitting a sensitive task between people prevents one person from committing and hiding fraud.","Outline Domain 3",[null,"One administrator holding every password concentrates control in a single person instead of splitting it.","A shared login destroys individual accountability and does not divide any sensitive task between people.","A manager approving their own expense report is exactly the conflict that separation of duties is meant to prevent."],3],["ic27",0,3,"In which access control model are permissions assigned to job functions and users gain them by being placed in those functions?",["Discretionary access control","Mandatory access control","Time-based access control","Role-based access control"],3,"RBAC grants permissions to roles, and users inherit them through role membership.","Outline Domain 3",["In DAC the resource owner decides who gets access, rather than permissions flowing from job functions.","MAC grants access by comparing system-enforced labels with clearances, not by role membership.","Time-based access control restricts when access is allowed; it does not assign permissions to job functions.",null],1],["ic28",0,3,"A military system grants access by comparing classification labels on data with users' clearances. Which model is this?",["Discretionary access control","Mandatory access control","Role-based access control","Rule-based access control"],1,"MAC is enforced by the system using labels and clearances, not by data owners.","Outline Domain 3",["In DAC the data owner chooses who has access, whereas here the system enforces labels and clearances.",null,"RBAC assigns permissions by job role, not by comparing classification labels with clearances.","Rule-based access control applies administrator-defined rules (such as firewall ACLs), not classification labels matched to clearances."],3],["ic29",0,3,"A user shares a folder and chooses which coworkers can open it. Which model is this?",["Mandatory access control","Discretionary access control","Role-based access control","Attribute labels set by the system"],1,"In DAC the owner of a resource decides who can access it.","Outline Domain 3",["In MAC the system enforces access based on labels, and users cannot choose who may open a resource.",null,"In RBAC access comes from job roles set by administrators, not from an owner picking individual coworkers.","Attribute labels set by the system describe a mandatory or attribute-based approach, not an owner choosing who gets access."],2],["ic30",0,3,"An employee is terminated today. What is the most important identity action?",["Reset their password next quarter","Move the account to another department","Leave the account active for handover","Disable or remove their access promptly"],3,"Timely deprovisioning prevents a former employee from using access they no longer should have.","Outline Domain 3",["Waiting until next quarter leaves a terminated employee's access usable for months.","Moving the account to another department keeps it active and still usable by the former employee.","Leaving the account active for handover lets someone who no longer works there keep access; handover should use a manager or shared resources instead.",null],2],["ic31",0,3,"What is privilege creep?",["Users keep accumulating permissions as they change roles","An attacker brute-forces a password","A badge reader fails open during a power cut","A firewall blocks legitimate traffic"],0,"Privilege creep happens when old access is not removed after role changes; access reviews catch it.","Outline Domain 3",[null,"Brute-forcing a password is a credential attack, not the gradual accumulation of permissions.","A badge reader failing open is a physical-security fail-safe behavior, unrelated to permissions building up over time.","A firewall blocking legitimate traffic is a false positive or misconfiguration, not privilege creep."],1],["ic32",0,3,"What is the main purpose of a periodic access review?",["Speeding up user logins","Installing missing patches","Confirming users still need the access they have","Resetting every password"],2,"Access reviews verify that current permissions are still appropriate and remove what is not.","Outline Domain 3",["Access reviews check whether permissions are appropriate; they have no effect on login speed.","Installing patches is vulnerability management, not a review of who has access to what.",null,"Resetting every password changes credentials but does not verify whether each user's access is still needed."],2],["ic33",0,3,"An access control vestibule (mantrap) at a data center entrance mainly prevents:",["Phishing","SQL injection","Tailgating","Malware infections"],2,"A vestibule lets only one authenticated person through at a time, stopping people from following someone in.","Outline Domain 3",["Phishing is an email or messaging attack, which a physical entry vestibule cannot stop.","SQL injection is an application-layer attack on databases, unrelated to controlling who walks through a door.",null,"Malware infections spread through software and networks, not through people following someone into a building."],2],["ic34",0,3,"A user types their username at a login screen. Which step is this?",["Identification","Authentication","Authorization","Accounting"],0,"Claiming an identity is identification; proving it with a password or factor is authentication.","Outline Domain 3",[null,"Authentication is proving the claimed identity, for example by entering a password, which comes after typing the username.","Authorization decides what the user may access after their identity is proven.","Accounting records what the user does after gaining access, not the act of claiming an identity."],1],["ic35",0,3,"What is the main benefit of single sign-on (SSO)?",["It removes the need for authentication","It guarantees no breaches","It eliminates the need for MFA","Users authenticate once to access multiple systems"],3,"SSO lets one authentication grant access to many applications, reducing password fatigue.","Outline Domain 3",["SSO does not remove authentication; the user still authenticates, just once for many systems.","No technology guarantees zero breaches, and a compromised SSO credential can actually expose many systems at once.","SSO does not replace MFA; because one login unlocks many systems, it should be protected with MFA.",null],1],["ic36",0,3,"What is the best practice for system administrators' privileged access?",["Use the admin account for daily email","Use a separate admin account only for admin tasks, protected with MFA","Share one admin account among the team","Turn off logging for admin accounts"],1,"Separate, MFA-protected admin accounts limit exposure and keep admin actions attributable.","Outline Domain 3",["Using an admin account for daily email exposes powerful privileges to phishing and malware.",null,"A shared admin account removes individual accountability, since actions cannot be traced to one person.","Turning off logging for admin accounts hides the most powerful actions from audit and investigation."],3],["ic37",0,4,"Which port does HTTPS use by default?",["80","443","22","25"],1,"HTTPS uses TCP 443; 80 is HTTP, 22 is SSH and 25 is SMTP.","Outline Domain 4",["Port 80 is the default for unencrypted HTTP, not HTTPS.",null,"Port 22 is used by SSH for secure remote shell access, not for HTTPS web traffic.","Port 25 is used by SMTP to send email, not for web traffic."],1],["ic38",0,4,"At which OSI layer does IP routing take place?",["Physical","Data link","Transport","Network"],3,"Routing by IP address happens at Layer 3, the network layer.","Outline Domain 4",["The physical layer (Layer 1) transmits raw bits over media and has no concept of IP addresses.","The data link layer (Layer 2) forwards frames using MAC addresses within a local network, not IP routing.","The transport layer (Layer 4) handles end-to-end delivery with TCP or UDP ports, not routing between networks.",null],1],["ic39",0,4,"Which protocol should replace Telnet for secure remote administration?",["SSH on port 22","FTP on port 21","HTTP on port 80","SNMP on port 161"],0,"SSH encrypts the session, while Telnet sends everything, including passwords, in clear text.","Outline Domain 4",[null,"FTP on port 21 transfers files and sends credentials in clear text, so it is neither secure nor a remote shell.","HTTP on port 80 is unencrypted web traffic and does not provide secure command-line administration.","SNMP on port 161 is for monitoring network devices, and older versions send community strings in clear text."],2],["ic40",0,4,"A company uses a SaaS email service. Which security responsibility remains with the company?",["Physical security of the data center","Patching the provider's hypervisors","Managing user access and the data it stores","Writing the application's code"],2,"Under shared responsibility, SaaS customers still own their identities, access settings and data.","Outline Domain 4",["In SaaS the provider is responsible for physical data center security, not the customer.","The provider patches its own hypervisors and infrastructure; customers have no access to them in SaaS.",null,"In SaaS the provider writes and maintains the application code; the customer only uses the application."],2],["ic41",0,4,"A distributed denial-of-service (DDoS) attack mainly targets which principle?",["Confidentiality","Integrity","Availability","Non-repudiation"],2,"DDoS floods a service so legitimate users cannot reach it.","Outline Domain 4",["DDoS does not expose data to unauthorized viewers, which is what confidentiality protects.","DDoS floods a service with traffic but does not normally modify data, so integrity is not the main target.",null,"Non-repudiation concerns proving who took an action, which a traffic flood does not attack."],1],["ic42",0,4,"What is the core idea of zero trust?",["Never trust, always verify each access request","Trust every device inside the perimeter","Allow access only through a VPN","Disable logging to improve speed"],0,"Zero trust removes implicit trust based on network location and verifies every request.","Outline Domain 4",[null,"Trusting every device inside the perimeter is the traditional castle-and-moat model that zero trust rejects.","A VPN only establishes a network connection and can still grant broad implicit trust once connected; zero trust verifies each request.","Disabling logging reduces visibility, while zero trust depends on continuous monitoring and verification."],1],["ic43",0,4,"An organization places its smart cameras and other IoT devices on their own VLAN. What is this?",["Load balancing","Port forwarding","Network address translation","Network segmentation to limit lateral movement"],3,"Segmentation isolates less-trusted devices so a compromise cannot easily spread.","Outline Domain 4",["Load balancing spreads traffic across servers for performance and availability; it does not isolate devices.","Port forwarding redirects incoming traffic on a port to an internal host and does nothing to separate device groups.","NAT translates private addresses to public ones; it does not place devices in an isolated segment.",null],2],["ic44",0,4,"What can an intrusion prevention system (IPS) do that an intrusion detection system (IDS) cannot?",["Record suspicious traffic","Block malicious traffic inline","Encrypt network traffic","Assign IP addresses"],1,"An IPS sits in the traffic path and can drop malicious packets; an IDS only alerts.","Outline Domain 4",["Recording suspicious traffic is something an IDS already does, so it is not the IPS's distinguishing capability.",null,"Neither an IDS nor an IPS encrypts traffic; that is the job of protocols such as TLS or IPsec.","Assigning IP addresses is the role of DHCP, not an intrusion detection or prevention system."],2],["ic45",0,4,"Several hospitals share a cloud built for their common regulatory needs. Which deployment model is this?",["Public","Community","Private","Hybrid"],1,"A community cloud is shared by organizations with common concerns such as compliance.","Outline Domain 4",["A public cloud is open to any customer, not built for a specific group with shared regulatory needs.",null,"A private cloud serves a single organization, not several hospitals sharing it.","A hybrid cloud combines two or more deployment models, such as private and public, rather than being shared by a group of similar organizations."],2],["ic46",0,4,"An employee works from coffee shop Wi-Fi. What best protects against man-in-the-middle attacks?",["Choosing a network with a longer name","Turning off the host firewall","Disabling automatic updates","Using a VPN or other encrypted connection"],3,"Encrypting traffic end to end keeps an attacker on the same network from reading or altering it.","Outline Domain 4",["The network name has no bearing on security, and attackers can easily create convincing fake network names.","Turning off the host firewall removes protection and makes the laptop more exposed on a public network.","Disabling automatic updates leaves known vulnerabilities unpatched and does nothing to protect traffic in transit.",null],3],["ic47",0,4,"What is a DMZ (screened subnet)?",["A network segment for public-facing servers, separated from the internal network","A wireless encryption protocol","A type of malware","An alternate recovery site"],0,"A DMZ hosts internet-facing services while firewalls keep them apart from internal systems.","Outline Domain 4",[null,"Wireless encryption protocols are standards like WPA2 or WPA3, not network segments for public servers.","Malware is malicious software, while a DMZ is a network design used for defense.","Alternate recovery sites (hot, warm or cold sites) are for business continuity, not for hosting public-facing servers."],1],["ic48",0,4,"Which describes Infrastructure as a Service (IaaS)?",["The provider manages the operating system and application","The customer rents a finished application","The customer rents virtual machines, storage and networking and manages the OS and apps","The customer only rents rack space for its own hardware"],2,"In IaaS the provider runs the physical infrastructure while the customer manages everything from the OS up.","Outline Domain 4",["When the provider manages the OS and application, that describes PaaS or SaaS rather than IaaS.","Renting a finished application is SaaS, where the customer only uses the software.",null,"Renting rack space for your own hardware is colocation, which is not a cloud service model."],2],["ic49",0,4,"Which cloud characteristic lets resources grow and shrink automatically with demand?",["Measured service","Broad network access","Rapid elasticity","Resource pooling"],2,"Rapid elasticity is the ability to scale resources quickly up or down.","Outline Domain 4",["Measured service means usage is metered and billed; it does not describe automatic scaling.","Broad network access means services are reachable over the network from many device types, not that they scale with demand.",null,"Resource pooling means the provider shares resources among many tenants; it enables elasticity but is not the scaling ability itself."],1],["ic50",0,4,"What does defense in depth mean?",["Using multiple layers of controls so one failure does not expose assets","Relying on one strong firewall","Using only encryption","Relying only on user training"],0,"Layered controls mean an attacker must defeat several defenses, not just one.","Outline Domain 4",[null,"Relying on one firewall is a single point of failure, the opposite of layered defense.","Encryption alone is just one control; if keys are stolen or access controls fail, nothing else protects the assets.","User training alone is a single layer, and people will still make mistakes without technical controls behind them."],1],["ic51",0,5,"Which incident response phase comes first?",["Containment","Eradication","Recovery","Preparation"],3,"Preparation (plans, team, tools, training) happens before any incident is detected.","Outline Domain 5",["Containment happens only after an incident has been detected and analyzed, so it cannot be first.","Eradication removes the threat after containment, well after the lifecycle begins.","Recovery restores normal operations near the end of the lifecycle, after eradication.",null],1],["ic52",0,5,"Which algorithm would you use to check that a downloaded file was not altered?",["AES","SHA-256","RSA","TLS"],1,"SHA-256 is a hash function; matching hashes show the file is unchanged.","Outline Domain 5",["AES is a symmetric encryption algorithm for confidentiality; it does not produce a checksum to verify file integrity.",null,"RSA is an asymmetric algorithm for encryption and signatures, not a hash for comparing file contents.","TLS is a protocol that secures data in transit; it is not an algorithm for checking a downloaded file after the fact."],1],["ic53",0,5,"Why do organizations send logs to a central SIEM?",["To make laptops faster","To correlate events across systems and alert on suspicious patterns","To replace backups","To encrypt hard drives"],1,"A SIEM aggregates and correlates logs, making attacks spanning several systems visible.","Outline Domain 5",["Sending logs to a SIEM does not speed up laptops; log forwarding actually uses a little endpoint resource.",null,"A SIEM stores and analyzes logs; it cannot restore systems or data the way backups do.","Disk encryption is an endpoint control and is not a function of a SIEM."],2],["ic54",0,5,"Which activity is part of system hardening?",["Installing every optional service","Keeping default passwords","Disabling logging","Removing unneeded services, changing defaults and applying patches"],3,"Hardening reduces the attack surface by removing what is not needed and securing what remains.","Outline Domain 5",["Installing every optional service increases the attack surface, the opposite of hardening.","Default passwords are widely published, so keeping them makes systems easier to compromise.","Disabling logging removes visibility into attacks and is not part of hardening.",null],2],["ic55",0,5,"What does a recovery point objective (RPO) define?",["The maximum acceptable data loss, measured in time","The maximum acceptable downtime","The total cost of recovery","The number of backup copies kept"],0,"RPO sets how much data, in time, can be lost; RTO sets how long systems can be down.","Outline Domain 5",[null,"Maximum acceptable downtime is described by the recovery time objective (RTO), not the RPO.","Recovery cost is a budget consideration, not what the RPO measures.","The number of backup copies is a backup policy detail; RPO defines how much data loss, in time, is acceptable."],1],["ic56",0,5,"A team has contained ransomware, removed it and restored systems. What should it do next?",["Detection","Preparation","Hold a lessons-learned review","Identification"],2,"Post-incident activity captures what went well and what to improve, closing the lifecycle.","Outline Domain 5",["Detection happens at the start of handling an incident, not after systems have already been restored.","Preparation is the initial phase before incidents occur; the team should first capture lessons that will feed back into it.",null,"Identification of the incident already happened before containment, so it is not the next step after recovery."],2],["ic57",0,5,"What does a data classification label mainly determine?",["Which hardware vendor to buy","The file size limit","How the data must be handled, such as encryption and who may access it","Which backup brand to use"],2,"Classification drives handling rules for protection, access, retention and destruction.","Outline Domain 5",["Classification labels describe data sensitivity, not which hardware vendor to purchase.","Classification does not set file size limits; it sets how the data must be protected and handled.",null,"Choosing a backup brand is a procurement decision; classification may influence backup requirements but not the brand."],1],["ic58",0,5,"A company is disposing of laptops with SSDs that held sensitive data. What is the best method?",["Physical destruction or cryptographic erasure","Deleting the files","A quick format","Renaming the folders"],0,"Deleting or formatting leaves recoverable data; destruction or crypto-erase makes it unrecoverable.","Outline Domain 5",[null,"Deleting files only removes references to the data, which can often still be recovered with forensic tools.","A quick format rewrites file system structures but leaves most of the underlying data recoverable.","Renaming folders changes only labels and leaves all of the sensitive data intact."],3],["ic59",0,5,"Alice wants to send Bob a confidential message using asymmetric encryption. Which key does she encrypt with?",["Alice's private key","Alice's public key","Bob's private key","Bob's public key"],3,"Encrypting with Bob's public key means only Bob's private key can decrypt it.","Outline Domain 5",["Encrypting with Alice's private key lets anyone with her public key decrypt it, which provides origin proof but not confidentiality.","Anything encrypted with Alice's public key can only be decrypted with Alice's private key, so Bob could not read it.","Alice should never have Bob's private key; only Bob holds it, and it is used to decrypt, not encrypt, the message.",null],3],["ic60",0,5,"What is the purpose of a business continuity plan?",["To restore only IT systems","To keep critical business functions running during and after a disruption","To discipline staff after incidents","To replace the incident response plan"],1,"BCP keeps essential operations going; disaster recovery focuses on restoring IT.","Outline Domain 5",["Restoring IT systems is the focus of disaster recovery, which is only one part of keeping the whole business running.",null,"Disciplining staff is an HR matter and is not the purpose of continuity planning.","A BCP complements the incident response plan rather than replacing it; each covers a different scope."],1],["x1",0,1,"A company posts signs at its entrance warning that trespassers will be prosecuted. Which type of security control are these signs acting as?",["Preventive","Detective","Deterrent","Corrective"],2,"Warning signs discourage people from attempting an action without physically stopping them, which is the definition of a deterrent control.","Domain 1: Security control types",["Preventive controls physically stop an action before it happens; a sign only discourages.","Detective controls identify incidents after they occur, not warn people in advance.",null,"Corrective controls fix damage after an incident, which a warning sign does not do."],2],["x2",0,1,"After a malware infection, an administrator wipes the affected server and restores it from a clean backup. Which control category does this restoration represent?",["Deterrent","Preventive","Detective","Corrective"],3,"Restoring a system to a good state after an incident fixes the damage, which is a corrective control.","Domain 1: Security control types",["Deterrent controls discourage behavior; they do not repair a compromised system.","Preventive controls stop an incident before it happens, not restore afterward.","Detective controls only identify that something occurred; they do not fix it.",null],2],["x3",0,1,"A risk analyst calculates the annualized loss expectancy in dollars to justify the cost of a control. Which type of risk assessment is being performed?",["Qualitative","Quantitative","Inherent","Residual"],1,"Assigning monetary values such as ALE is a quantitative assessment; qualitative methods use ratings like high or low instead.","Domain 1: Risk assessment",["Qualitative assessment uses ratings like high or low, not dollar figures such as ALE.",null,"Inherent risk is the risk level before controls, not a method of assessment.","Residual risk is what remains after controls, not an assessment technique."],3],["x4",0,1,"A privacy officer wants individuals to control how their personal data is collected and used. Which concept does this goal most directly support?",["Availability","Non-repudiation","Privacy","Integrity"],2,"Giving people control over how their personal information is handled is the core idea of privacy.","Domain 1: Privacy",["Availability concerns keeping systems accessible, not personal data control.","Non-repudiation prevents denying an action; it is not about personal data control.",null,"Integrity concerns preventing unauthorized changes, not who controls personal data."],2],["x5",0,1,"Leadership reviews a low-likelihood, low-impact risk, documents the decision, and chooses to take no further action. Which risk treatment is this?",["Mitigation","Acceptance","Avoidance","Transference"],1,"Knowingly documenting a risk and deciding to live with it, rather than acting, is risk acceptance.","Domain 1: Risk treatment",["Mitigation means adding controls to lower the risk, which was not done here.",null,"Avoidance means stopping the risky activity entirely, not keeping it as is.","Transference shifts the risk to a third party, such as insurance, which did not happen."],3],["x6",0,1,"An application allows sign-in only when the request originates from an approved location and denies all others. Which authentication factor is being used?",["Something you know","Something you have","Something you are","Somewhere you are"],3,"Using the user's location to allow or deny access is the 'somewhere you are' (location) factor.","Domain 1: Authentication factors",["Something you know is a password or PIN, not the request's location.","Something you have is a token or device, not a location.","Something you are is a biometric trait, not a location.",null],3],["x7",0,1,"A file server uses redundant disks and a backup power supply so it keeps serving files if a disk or the power fails. Which security principle does this support?",["Confidentiality","Integrity","Availability","Non-repudiation"],2,"Redundancy keeps a service reachable despite component failure, which protects availability.","Domain 1: CIA triad",["Confidentiality concerns keeping data secret, not keeping the service running.","Integrity concerns preventing unauthorized changes, not uptime.",null,"Non-repudiation concerns proving who acted, not keeping a service available."],2],["x8",0,1,"According to guidance on the ISC2 Code of Ethics, if two canons appear to conflict, how should a member resolve the conflict?",["Follow whichever is easiest","Ignore both canons","Ask the client to decide","Apply the canons in the order they are listed"],3,"The canons are meant to be applied in their stated order of priority when they seem to conflict.","Domain 1: ISC2 Code of Ethics",["Choosing the easiest option ignores the canons' defined priority order.","Ignoring the canons contradicts a member's obligation to uphold them.","The canons, not the client, determine how conflicts are resolved.",null],3],["x9",0,1,"An employee inserts a smart card and enters a PIN to log in. The smart card itself represents which authentication factor?",["Something you know","Something you are","Somewhere you are","Something you have"],3,"A physical smart card is a token you possess, so it is a 'something you have' factor; the PIN is 'something you know'.","Domain 1: Authentication factors",["Something you know refers to the PIN, not the physical card.","Something you are is a biometric trait, not a possessed object.","Somewhere you are is location, which the card does not represent.",null],1],["x10",0,1,"A security team documents 'organized crime groups seeking financial gain' as a source of potential harm. What are they identifying?",["A vulnerability","A control","A threat","An asset"],2,"An actor or event that could cause harm is a threat; a vulnerability is the weakness it would exploit.","Domain 1: Risk terminology",["A vulnerability is a weakness, not the actor that would exploit it.","A control is a safeguard, not a source of harm.",null,"An asset is something of value to protect, not a source of harm."],3],["x11",0,1,"A door lock stops an unauthorized person from entering a wiring closet. Which control function does the lock primarily perform?",["Detective","Corrective","Preventive","Compensating"],2,"A lock stops the unwanted action before it happens, which is a preventive control function.","Domain 1: Security control types",["Detective controls identify an event after it happens, not block entry.","Corrective controls repair damage afterward, not prevent entry.",null,"A compensating control substitutes for another; the lock directly prevents access."],2],["x12",0,1,"An administrator wants to confirm that a configuration file has not been altered since it was approved. Which technique best verifies this?",["Comparing a cryptographic hash of the file","Encrypting the file with a public key","Compressing the file","Renaming the file"],0,"A cryptographic hash changes if any content changes, so matching hashes prove the file is unaltered.","Domain 1: Integrity",[null,"Public-key encryption protects confidentiality, not detection of alteration.","Compression only reduces size and does not reveal tampering.","Renaming a file does nothing to verify its contents are unchanged."],2],["x13",0,1,"After a company applies controls to reduce a risk, some risk still remains. What is this remaining risk called?",["Inherent risk","Total risk","Transferred risk","Residual risk"],3,"The risk left over after controls are applied is residual risk; inherent risk is the level before controls.","Domain 1: Risk terminology",["Inherent risk is the level before any controls are applied, not what remains.","Total risk is the full exposure, not the leftover after controls.","Transferred risk is passed to another party, not what stays with the organization.",null],3],["x14",0,1,"Before assessing risk, a team catalogs the servers, data, and applications the business depends on. What are these items called?",["Threats","Vulnerabilities","Assets","Controls"],2,"Things of value that the organization needs to protect are its assets.","Domain 1: Risk terminology",["Threats are sources of harm, not the valuable items being catalogued.","Vulnerabilities are weaknesses, not the resources the business relies on.",null,"Controls are safeguards, not the resources being protected."],2],["x15",0,1,"Regulators ask a company to explain how its AI model reached a lending decision. Which quality of trustworthy AI does this request emphasize?",["Elasticity","Redundancy","Throughput","Transparency"],3,"Being able to explain how an AI reaches a decision is transparency, a key element of trustworthy AI.","Domain 1: AI and CIA",["Elasticity is a cloud scaling property, unrelated to explaining AI decisions.","Redundancy supports availability, not explainability of AI decisions.","Throughput measures processing volume, not the ability to explain decisions.",null],2],["x16",0,2,"A document sets the minimum security configuration that every company laptop must meet. Which type of governance document is this?",["Guideline","Policy","Baseline","Procedure"],2,"A baseline defines the minimum acceptable configuration or security level; a policy states high-level intent.","Domain 2: Policies and standards",["A guideline is only a recommendation, not a mandatory minimum configuration.","A policy states high-level intent, not a specific minimum configuration.",null,"A procedure gives step-by-step instructions, not a minimum configuration standard."],1],["x17",0,2,"A retailer that stores and processes customer credit card data must comply with which requirement set?",["PCI DSS","HIPAA","GDPR","SOX"],0,"PCI DSS governs the handling of payment card data; HIPAA covers health data and GDPR covers EU personal data.","Domain 2: Laws and regulations",[null,"HIPAA covers protected health information, not payment card data.","GDPR covers EU personal data, not specifically payment cards.","SOX addresses financial reporting controls, not cardholder data."],1],["x18",0,2,"An organization defines how much it will allow a specific project to deviate from its stated risk appetite. This acceptable deviation is its:",["Risk tolerance","Risk transfer","Risk register","Risk avoidance"],0,"Risk tolerance is the acceptable variation around the broad risk appetite for a given activity.","Domain 2: Risk appetite and tolerance",[null,"Risk transfer shifts risk to a third party; it is not the acceptable deviation.","A risk register is a list of risks, not a measure of acceptable deviation.","Risk avoidance removes the activity; it does not describe acceptable variation."],3],["x19",0,2,"A company is concerned that a software supplier could introduce vulnerabilities into delivered code. This is an example of:",["Insider threat","Third-party (supply chain) risk","Physical risk","Residual risk"],1,"Risk arising from vendors and suppliers is third-party or supply chain risk; an insider threat comes from within.","Domain 2: Third-party risk",["An insider threat comes from within the organization, not from a supplier.",null,"Physical risk relates to facilities and hardware, not supplier-introduced code.","Residual risk is what remains after controls, not a supplier-origin risk."],2],["x20",0,2,"A document recommends, but does not require, that staff use a password manager. What kind of governance document is it?",["Policy","Standard","Procedure","Guideline"],3,"Optional recommendations are guidelines; policies and standards are mandatory.","Domain 2: Policies and standards",["A policy is mandatory, but this document only recommends.","A standard sets mandatory requirements, unlike an optional recommendation.","A procedure gives required steps, not optional advice.",null],1],["x21",0,2,"Which law primarily governs the protection of personal data belonging to individuals in the European Union?",["PCI DSS","HIPAA","GLBA","GDPR"],3,"The GDPR is the EU regulation for personal data protection; the others cover payment cards, health, and US financial data.","Domain 2: Laws and regulations",["PCI DSS governs payment card data, not general EU personal data.","HIPAA covers US health information, not EU personal data broadly.","GLBA covers US financial institutions, not EU personal data.",null],1],["x22",0,2,"Which group in an organization is responsible for setting the risk appetite?",["The help desk","External attackers","End users","Senior leadership"],3,"Setting risk appetite is a governance decision owned by senior leadership and the board.","Domain 2: Governance and leadership",["The help desk handles support tasks, not setting organizational risk appetite.","External attackers are a threat, not decision-makers for the organization.","End users follow policy; they do not set risk appetite.",null],2],["x23",0,2,"Which metric is designed to indicate performance against a goal rather than warn of rising risk exposure?",["Key risk indicator","Recovery time objective","Annualized loss expectancy","Key performance indicator"],3,"A KPI measures progress toward a goal; a KRI is chosen specifically to signal increasing risk.","Domain 2: Program metrics",["A key risk indicator warns of rising risk, not performance toward a goal.","A recovery time objective is a continuity target, not a performance metric here.","Annualized loss expectancy is a risk cost estimate, not a performance measure.",null],2],["x24",0,2,"Which of the following is the best evidence that a security awareness program is changing employee behavior?",["Number of training slides","Total employees hired","Reduced click rate on phishing simulations","Number of policies written"],2,"A falling phishing-simulation click rate shows behavior is changing; counting slides or policies does not.","Domain 2: Security awareness",["Counting slides measures effort, not any change in employee behavior.","The number of employees hired says nothing about awareness behavior.",null,"The number of policies written does not show behavior has changed."],3],["x25",0,2,"An auditor finds staff are skipping a required approval step. Which document should define that mandatory requirement at a high level?",["Guideline","Policy","Newsletter","Marketing brochure"],1,"Mandatory requirements are stated in a policy; guidelines are only recommendations and the others are not governance documents.","Domain 2: Policies and standards",["A guideline is only a recommendation, not a mandatory required step.",null,"A newsletter is informal communication, not a governance document.","A marketing brochure is promotional material, not a governance document."],2],["x26",0,3,"A fully cleared analyst is denied access to a classified project that is unrelated to their duties. Which principle enforces this restriction?",["Separation of duties","Need to know","Single sign-on","Federation"],1,"Need to know limits access to information a person actually requires for their job, even if they have clearance.","Domain 3: Least privilege and need to know",["Separation of duties splits a task among people; it is not about topical access limits.",null,"Single sign-on is an authentication convenience, not an access-limiting principle.","Federation extends identity across organizations; it does not restrict by need."],3],["x27",0,3,"A user signs into a partner company's website using their own employer's identity provider. What makes this possible?",["Identity federation","Mandatory access control","Privilege creep","Tailgating"],0,"Federation lets one organization trust another's identity provider so users can log in across domains.","Domain 3: Federation and SSO",[null,"Mandatory access control enforces labels; it does not enable cross-company login.","Privilege creep is unwanted access buildup, not a login mechanism.","Tailgating is a physical entry attack, unrelated to federated login."],2],["x28",0,3,"On a new hire's first day, accounts and access are created for them based on their assigned role. Which identity lifecycle stage is this?",["Deprovisioning","Access review","Recertification","Provisioning"],3,"Creating identities and granting initial access is provisioning; deprovisioning removes access when someone leaves.","Domain 3: Identity lifecycle",["Deprovisioning removes access when a user leaves, the opposite of onboarding.","An access review checks existing access; it does not create it on day one.","Recertification confirms existing access remains valid, not initial creation.",null],2],["x29",0,3,"A firewall permits traffic only during business hours, regardless of who the user is. Which access control type does this represent?",["Discretionary","Role-based","Rule-based","Mandatory"],2,"Rule-based control applies conditions such as time of day to everyone; RBAC would decide by the user's role instead.","Domain 3: Access control models",["Discretionary control lets owners decide access, not a fixed time rule for all.","Role-based control decides by the user's role, not a blanket time condition.",null,"Mandatory control uses labels and clearances, not time-of-day rules."],3],["x30",0,3,"Which type of solution vaults, rotates, and monitors the credentials used for administrative accounts?",["Privileged access management","Single sign-on","A guest VLAN","A honeypot"],0,"PAM specifically secures, rotates, and audits privileged credentials; SSO handles ordinary user logins.","Domain 3: Privileged access management",[null,"Single sign-on simplifies user logins; it does not vault admin credentials.","A guest VLAN isolates visitor traffic, unrelated to privileged credentials.","A honeypot is a decoy system, not a credential management tool."],2],["x31",0,3,"An attacker carrying boxes asks an employee to hold the secure door open for them. Which threat is this?",["Phishing","Tailgating","Spoofing","DDoS"],1,"Following an authorized person through a controlled door is tailgating; phishing and spoofing are not physical entry.","Domain 3: Physical access controls",["Phishing uses deceptive messages, not physical door access.",null,"Spoofing falsifies identity in data, not physical entry through a door.","A DDoS floods a service; it is not a physical entry technique."],3],["x32",0,3,"Periodically moving employees through different sensitive positions helps expose hidden fraud. What is this practice called?",["Job rotation","Least privilege","Federation","Provisioning"],0,"Job rotation moves people through duties so wrongdoing that depends on one person staying put is uncovered.","Domain 3: Separation of duties",[null,"Least privilege limits access levels; it is not the practice of rotating staff.","Federation links identity across organizations, unrelated to rotating duties.","Provisioning creates accounts and access, not rotation of personnel."],3],["x33",0,3,"A badge system records every entry to the data center along with the time and identity. What does this recording primarily support?",["Prevention of entry","Accounting and auditing of access","Encryption of badges","Deprovisioning"],1,"Keeping a record of who accessed what and when is the accounting or auditing function.","Domain 3: Accounting and access reviews",["A record of entries documents access; it does not by itself prevent entry.",null,"Encrypting badges protects credentials, not the logging of who entered.","Deprovisioning removes access; it is not the recording of entries."],3],["x34",0,3,"In a mandatory access control (MAC) system, why can a user not simply share a file they own with a colleague?",["Access is enforced by system-wide labels and clearances, not user choice","Files cannot be shared in any operating system","The colleague does not have a username","MAC applies only to printers"],0,"In MAC the system enforces access using labels and clearances set by policy, so owners cannot grant access on their own.","Domain 3: Access control models",[null,"Files can be shared in many systems; the constraint is specific to MAC.","Lacking a username is not why MAC blocks owner-granted sharing.","MAC governs data and systems broadly, not only printers."],3],["x35",0,3,"Every quarter, managers must confirm that each team member still needs their current access. What is this process called?",["Access recertification","Single sign-on","Provisioning","Password rotation"],0,"Periodically confirming that access is still appropriate is access recertification or review.","Domain 3: Periodic access reviews",[null,"Single sign-on is an authentication feature, not a periodic access check.","Provisioning grants initial access; it does not confirm ongoing need.","Password rotation changes credentials, not whether access is still needed."],2],["x36",0,3,"An employee moves from finance to marketing but keeps their old finance system access. What should deprovisioning on transfer prevent?",["Tailgating","DDoS","Data classification","Privilege creep"],3,"Accumulating unneeded access across role changes is privilege creep, which timely removal on transfer prevents.","Domain 3: Identity lifecycle",["Tailgating is a physical entry attack, not an access-accumulation issue.","A DDoS is an availability attack, unrelated to leftover access on transfer.","Data classification labels information; it does not concern access buildup.",null],2],["x37",0,3,"To reduce insider fraud, the person who requests new access must not be the same person who approves it. Which principle is applied?",["Least privilege","Separation of duties","Federation","Elasticity"],1,"Splitting request and approval between two people is separation of duties; least privilege limits how much access is granted.","Domain 3: Separation of duties",["Least privilege limits how much access is granted, not who approves it.",null,"Federation links identity across organizations, not approval separation.","Elasticity is a cloud scaling property, unrelated to approval duties."],3],["x38",0,4,"A helpdesk technician connects to a Windows desktop remotely using Remote Desktop Protocol. Which default port does that use?",["22","443","3389","53"],2,"RDP uses TCP 3389 by default; 22 is SSH, 443 is HTTPS, and 53 is DNS.","Domain 4: Common ports",["Port 22 is used by SSH, not Remote Desktop Protocol.","Port 443 is used by HTTPS, not RDP.",null,"Port 53 is used by DNS, not RDP."],1],["x39",0,4,"Which port does a standard DNS name lookup normally use?",["80","53","25","389"],1,"DNS name resolution uses port 53; port 80 is HTTP, port 25 is SMTP for email, and port 389 is LDAP directory access.","Domain 4: Common ports",["Port 80 is used by HTTP, not DNS lookups.",null,"Port 25 is used by SMTP, not DNS.","Port 389 is used by LDAP, not DNS."],1],["x40",0,4,"Email transferred between mail servers commonly uses which port?",["110","143","25","3389"],2,"SMTP uses port 25 for server-to-server mail; 110 is POP3 and 143 is IMAP for retrieval.","Domain 4: Common ports",["Port 110 is used by POP3 for mail retrieval, not server-to-server sending.","Port 143 is used by IMAP for mail retrieval, not sending between servers.",null,"Port 3389 is used by RDP, not email transfer."],1],["x41",0,4,"A company keeps sensitive records in its private cloud but bursts to a public cloud during peak demand. Which deployment model is this?",["Public","Community","Hybrid","Private"],2,"Combining private and public clouds that work together is a hybrid cloud deployment.","Domain 4: Cloud deployment models",["A public cloud alone does not include the company's private cloud portion.","A community cloud is shared by similar organizations, not a private-plus-public mix.",null,"A private cloud alone excludes the public-cloud bursting described."],3],["x42",0,4,"A developer deploys code to a service where the provider manages the operating system and runtime but the developer manages the application. Which service model is this?",["IaaS","PaaS","SaaS","On-premises"],1,"PaaS provides a managed platform for applications while the provider handles the OS and runtime beneath it.","Domain 4: Cloud service models",["In IaaS the customer manages the operating system, unlike the described service.",null,"In SaaS the provider manages the whole application, not just the platform.","On-premises means the customer runs all infrastructure themselves."],2],["x43",0,4,"A data center applies security policies between individual workloads, not just at the network edge. What is this approach called?",["Micro-segmentation","Port forwarding","Network address translation","Broadcasting"],0,"Enforcing controls between individual workloads is micro-segmentation, a finer-grained form of segmentation.","Domain 4: Network design",[null,"Port forwarding redirects specific traffic, not policy between workloads.","Network address translation remaps addresses; it does not segment workloads.","Broadcasting sends traffic to all hosts, the opposite of isolating workloads."],3],["x44",0,4,"An attacker secretly relays and can alter the messages between two parties who believe they are communicating directly. Which attack is this?",["Denial of service","Data poisoning","Tailgating","Man-in-the-middle"],3,"Intercepting and possibly altering traffic between two parties is a man-in-the-middle attack.","Domain 4: Network threats",["A denial of service disrupts availability; it does not relay messages secretly.","Data poisoning corrupts training data, not live communications between parties.","Tailgating is a physical entry attack, not message interception.",null],2],["x45",0,4,"Which device filters traffic between network segments based on rules about addresses, ports, and protocols?",["Switch","Firewall","Hub","Wireless access point"],1,"A firewall enforces rules to allow or block traffic between segments; a switch or hub just forwards frames.","Domain 4: Network defenses",["A switch forwards frames within a segment; it does not filter by rules.",null,"A hub simply repeats traffic to all ports without filtering.","A wireless access point provides connectivity, not rule-based filtering."],1],["x46",0,4,"A remote worker needs an encrypted tunnel back to the corporate network over the public internet. Which technology provides this?",["VLAN","DMZ","VPN","NAT"],2,"A VPN creates an encrypted tunnel across untrusted networks; a VLAN and DMZ are network segments, not tunnels.","Domain 4: Network defenses",["A VLAN segments a local network; it does not tunnel across the internet.","A DMZ is a screened subnet for public services, not an encrypted tunnel.",null,"NAT translates addresses; it does not create an encrypted tunnel."],2],["x47",0,4,"A cloud customer is billed based on the exact amount of storage and compute they consume. Which cloud characteristic is this?",["Resource pooling","Measured service","Broad network access","Multitenancy"],1,"Metering and billing by actual usage is the measured service characteristic of cloud computing.","Domain 4: Cloud characteristics",["Resource pooling shares infrastructure among tenants, not usage-based billing.",null,"Broad network access means reaching services over the network, not metering.","Multitenancy means many customers share resources, not billing by usage."],3],["x48",0,4,"In an Infrastructure as a Service (IaaS) deployment, who is responsible for patching the guest operating system?",["The cloud provider","No one","The end user's ISP","The customer"],3,"Under IaaS the provider runs the physical infrastructure while the customer manages the OS upward, including patches.","Domain 4: Shared responsibility model",["In IaaS the provider manages only the physical layer, not the guest OS.","Guest OS patching is a defined responsibility, so it is not left to no one.","The ISP provides connectivity and does not patch a customer's guest OS.",null],3],["x49",0,4,"Packets arrive on the network claiming a source IP address that does not really belong to the sender in order to bypass a filter. Which technique is this?",["Spoofing","Segmentation","Encryption","Load balancing"],0,"Forging a source address to appear as a trusted host is spoofing.","Domain 4: Network threats",[null,"Segmentation divides a network; it is not the act of forging source addresses.","Encryption protects data confidentiality, not forging source addresses.","Load balancing distributes traffic; it does not falsify source addresses."],2],["x50",0,4,"At which layer of the TCP/IP model do TCP and UDP operate, using port numbers to identify applications?",["Application","Transport","Internet","Link"],1,"TCP and UDP with their port numbers operate at the transport layer of the TCP/IP model.","Domain 4: TCP/IP model",["The application layer handles services like HTTP, not TCP/UDP ports directly.",null,"The internet layer handles IP addressing and routing, not port numbers.","The link layer handles local frame delivery, not transport ports."],1],["x51",0,5,"Analysts isolate an infected laptop from the network to stop malware from spreading to other systems. Which incident response phase is this?",["Detection","Containment","Recovery","Preparation"],1,"Limiting the spread of an active incident is containment; recovery comes later when systems are restored.","Domain 5: Incident response lifecycle",["Detection is recognizing the incident, which already happened before isolating.",null,"Recovery restores systems to normal after the threat is removed, not now.","Preparation happens before any incident, not during an active response."],2],["x52",0,5,"Two systems share the same secret key to encrypt and decrypt large amounts of data quickly. Which type of encryption is this?",["Asymmetric","Hashing","Symmetric","Steganography"],2,"Using one shared secret key for both encryption and decryption is symmetric encryption; asymmetric uses a key pair.","Domain 5: Encryption",["Asymmetric encryption uses a public and private key pair, not one shared key.","Hashing is one-way and does not decrypt data.",null,"Steganography hides data in other data; it is not shared-key encryption."],2],["x53",0,5,"A business decides its order system must be back in operation within four hours of an outage. Which metric expresses this target?",["Recovery point objective","Mean time between failures","Annualized rate of occurrence","Recovery time objective"],3,"The maximum acceptable downtime before restoration is the recovery time objective; RPO measures acceptable data loss.","Domain 5: Business continuity",["A recovery point objective measures acceptable data loss, not downtime.","Mean time between failures measures reliability, not restoration targets.","Annualized rate of occurrence estimates event frequency, not downtime.",null],2],["x54",0,5,"Before writing a continuity plan, a company identifies which functions are most critical and the impact of losing them. What is this analysis called?",["Business impact analysis","Penetration test","Access review","Patch cycle"],0,"A business impact analysis identifies critical functions and the effect of their loss, feeding RTO and RPO decisions.","Domain 5: Business continuity",[null,"A penetration test probes for vulnerabilities, not criticality of functions.","An access review checks user permissions, not business function impact.","A patch cycle schedules updates; it does not analyze business impact."],3],["x55",0,5,"A proposed firewall rule change must be reviewed and approved before it is applied to production systems. Which process governs this?",["Change management","Incident response","Data classification","Federation"],0,"Reviewing and approving changes before they reach production is change management, which reduces outages and errors.","Domain 5: Change management",[null,"Incident response handles active incidents, not planned production changes.","Data classification labels information; it does not approve changes.","Federation links identity across organizations, unrelated to change approval."],3],["x56",0,5,"A policy states that financial records must be kept for seven years and then securely destroyed. Which data security concept is this?",["Data retention","Encryption","Segmentation","Non-repudiation"],0,"Rules on how long to keep data before disposal are data retention; encryption protects it but does not set a timeline.","Domain 5: Data security",[null,"Encryption protects data confidentiality but does not set a keep-and-destroy timeline.","Segmentation isolates networks; it does not govern how long data is kept.","Non-repudiation proves who acted; it does not concern retention periods."],2],["x57",0,5,"After containing a breach, the team removes the attacker's malware and closes the vulnerability that was exploited. Which phase is this?",["Detection","Eradication","Preparation","Lessons learned"],1,"Removing the threat and its root cause from the environment is eradication, which follows containment.","Domain 5: Incident response lifecycle",["Detection recognizes the incident; the malware has already been found here.",null,"Preparation happens before incidents, not while removing an active threat.","Lessons learned is the final review phase, after eradication and recovery."],2],["x58",0,5,"An organization keeps a fully equipped, running duplicate facility ready to take over operations almost immediately. Which recovery option is this?",["Cold site","Warm site","Hot site","Reciprocal agreement"],2,"A hot site is fully equipped and running so operations can switch over quickly; a cold site has little or no equipment ready.","Domain 5: Disaster recovery",["A cold site has little equipment ready and cannot take over immediately.","A warm site is partially equipped and needs setup before taking over.",null,"A reciprocal agreement shares another organization's site, not a ready duplicate."],3],["x59",0,5,"A team regularly scans systems, prioritizes findings by risk, and tracks their remediation over time. What is this ongoing process called?",["Vulnerability management","Incident eradication","Data labeling","Change freeze"],0,"The continuous cycle of finding, prioritizing, and fixing weaknesses is vulnerability management.","Domain 5: Vulnerability management",[null,"Incident eradication removes a specific threat; it is not the ongoing scan cycle.","Data labeling classifies information; it does not find and fix weaknesses.","A change freeze halts changes; it is not vulnerability remediation."],2],["x60",0,5,"A SOC analyst reviews incoming SIEM alerts to decide which need investigation and which are false positives. What is this activity called?",["Event triage","Backup rotation","Key rotation","Provisioning"],0,"Sorting and prioritizing alerts to decide what to investigate is event triage.","Domain 5: Logging and monitoring",[null,"Backup rotation manages backup media, not alert investigation.","Key rotation changes cryptographic keys, unrelated to reviewing alerts.","Provisioning creates accounts and access, not alert prioritization."],3]]);
